static JSValue
nd_mql_addListener(JSContext *ctx, JSValueConst this_val,
                   int argc, JSValueConst *argv)
{
    if (argc < 1 || !JS_IsFunction(ctx, argv[0])) return JS_UNDEFINED;
    JSValueConst args[2] = { JS_NewString(ctx, "change"), argv[0] };
    JSValue r = nd_target_addEventListener(ctx, this_val, 2, args);
    JS_FreeValue(ctx, args[0]);
    return r;
}

static JSValue
nd_mql_removeListener(JSContext *ctx, JSValueConst this_val,
                      int argc, JSValueConst *argv)
{
    if (argc < 1) return JS_UNDEFINED;
    JSValueConst args[2] = { JS_NewString(ctx, "change"), argv[0] };
    JSValue r = nd_target_removeEventListener(ctx, this_val, 2, args);
    JS_FreeValue(ctx, args[0]);
    return r;
}

static gint64
nd_js_eval_budget_us(void)
{
    const nd_config *c = nd_config_get();
    int ms = c ? c->js_eval_budget_ms : 5000;
    if (ms <= 0) ms = 5000;
    if (ms > ND_JS_EVAL_BUDGET_MAX_MS) ms = ND_JS_EVAL_BUDGET_MAX_MS;
    return (gint64)ms * 1000LL;
}

#define ND_JS_MONITOR_LIMIT_US (60LL * 1000000LL)

static int
nd_js_interrupt_cb(JSRuntime *rt, void *opaque)
{
    (void)rt;
    nd_js *js = opaque;
    if (!js) return 0;
    if (js->halted) return 1;
    gint64 now = g_get_monotonic_time();
    if (js->js_monitor_deadline_us != 0 && now > js->js_monitor_deadline_us) {
        js->halted = TRUE;
        g_warning("[js] monitor: page JavaScript ran longer than %d s — halting it",
                  (int)(ND_JS_MONITOR_LIMIT_US / 1000000LL));
        return 1;
    }
    if (!js->in_pump && now - js->last_pump_us > 100000) {
        js->last_pump_us = now;
        js->in_pump = TRUE;
        for (int i = 0; i < 8 && g_main_context_pending(NULL); i++)
            g_main_context_iteration(NULL, FALSE);
        js->in_pump = FALSE;
        if (js->halted) return 1;
    }
    if (js->eval_deadline_us == 0) return 0;
    return now > js->eval_deadline_us ? 1 : 0;
}

void
nd_js_halt(nd_js *js)
{
    if (!js) return;
    js->halted = TRUE;
}

gboolean
nd_js_is_halted(const nd_js *js)
{
    return js && js->halted;
}

typedef struct nd_budget_guard {
    gint64 saved;
} nd_budget_guard;

static void
nd_js_budget_push(nd_js *js, nd_budget_guard *g)
{
    if (!js || !g) return;
    g->saved = js->eval_deadline_us;
    gint64 now = g_get_monotonic_time();
    if (g->saved == 0)
        js->js_monitor_deadline_us = now + ND_JS_MONITOR_LIMIT_US;
    gint64 fresh = now + nd_js_eval_budget_us();
    if (g->saved == 0 || fresh < g->saved)
        js->eval_deadline_us = fresh;
}

static void
nd_js_budget_pop(nd_js *js, nd_budget_guard *g)
{
    if (!js || !g) return;
    js->eval_deadline_us = g->saved;
    if (g->saved == 0)
        js->js_monitor_deadline_us = 0;
}

