static JSValue
nd_ctor_hasInstance(JSContext *ctx, JSValueConst this_val,
                    int argc, JSValueConst *argv, int magic)
{
    (void)this_val;
    if (argc < 1 || magic < 0 ||
        magic >= (int)G_N_ELEMENTS(nd_instof_table))
        return JS_FALSE;
    const nd_node *n = nd_unwrap_element(argv[0]);
    if (!n) return JS_FALSE;
    const nd_instof_def *d = &nd_instof_table[magic];
    switch (d->special) {
    case ND_INSTOF_FRAGMENT:
        return JS_NewBool(ctx, (n->flags & ND_NODE_FRAGMENT) != 0);
    case ND_INSTOF_TEXT:
        return JS_NewBool(ctx, n->kind == ND_NODE_TEXT);
    case ND_INSTOF_COMMENT:
        return JS_NewBool(ctx, n->kind == ND_NODE_COMMENT);
    case ND_INSTOF_CHARDATA:
        return JS_NewBool(ctx, n->kind == ND_NODE_TEXT ||
                               n->kind == ND_NODE_COMMENT);
    default:
        break;
    }
    if (n->kind != ND_NODE_ELEMENT || !n->name || !d->tags)
        return JS_FALSE;
    const char *s = d->tags;
    size_t nlen = strlen(n->name);
    while (*s) {
        while (*s == ' ') s++;
        const char *tok = s;
        while (*s && *s != ' ') s++;
        size_t tlen = (size_t)(s - tok);
        if (tlen == nlen && g_ascii_strncasecmp(tok, n->name, tlen) == 0)
            return JS_TRUE;
    }
    return JS_FALSE;
}

static void
nd_install_hasinstance(JSContext *ctx, JSValueConst global)
{
    JSValue sym = JS_GetPropertyStr(ctx, global, "Symbol");
    if (!JS_IsObject(sym)) { JS_FreeValue(ctx, sym); return; }
    JSValue hi = JS_GetPropertyStr(ctx, sym, "hasInstance");
    JS_FreeValue(ctx, sym);
    JSAtom hi_atom = JS_ValueToAtom(ctx, hi);
    JS_FreeValue(ctx, hi);
    for (int i = 0; i < (int)G_N_ELEMENTS(nd_instof_table); i++) {
        JSValue ctor = JS_GetPropertyStr(ctx, global, nd_instof_table[i].ctor);
        if (JS_IsObject(ctor)) {
            JSValue fn = JS_NewCFunctionMagic(ctx, nd_ctor_hasInstance,
                "[Symbol.hasInstance]", 1, JS_CFUNC_generic_magic, i);
            JS_DefinePropertyValue(ctx, ctor, hi_atom, fn, JS_PROP_CONFIGURABLE);
        }
        JS_FreeValue(ctx, ctor);
    }
    JS_FreeAtom(ctx, hi_atom);
}

static JSValue
nd_element_get_tagName(JSContext *ctx, JSValueConst this_val)
{
    const nd_node *n = nd_unwrap_element(this_val);
    if (!n || !n->name) return JS_NULL;
    for (const char *p = n->name; *p; p++)
        if (*p >= 'A' && *p <= 'Z')
            return JS_NewString(ctx, n->name);
    char *up = g_ascii_strup(n->name, -1);
    JSValue v = JS_NewString(ctx, up);
    g_free(up);
    return v;
}

static JSValue
nd_element_get_localName(JSContext *ctx, JSValueConst this_val)
{
    const nd_node *n = nd_unwrap_element(this_val);
    if (!n || !n->name) return JS_NULL;
    return JS_NewString(ctx, n->name);
}

static const char *const nd_reflected_attr_names[] = {
    "title", "name", "alt", "src", "href", "type", "placeholder", "lang", "dir",
    "action", "method", "enctype", "target", "rel", "accept", "accept-charset",
    "autocomplete", "list", "min", "max", "step", "pattern", "spellcheck",
    "crossorigin", "referrerpolicy", "decoding", "loading", "fetchpriority",
    "sizes", "srcset", "usemap", "inputmode", "size", "cols", "rows",
    "maxlength", "minlength", "coords", "shape",
    "formaction", "formmethod", "formenctype", "formtarget",
    "integrity", "kind", "label", "hreflang", "charset", "content",
    "http-equiv", "contenteditable", "slot", "is", "role",
    "aria-label", "aria-hidden", "aria-disabled", "aria-pressed",
    "aria-expanded", "aria-controls", "aria-describedby",
    "aria-labelledby", "aria-live", "aria-busy", "aria-checked",
    "aria-current", "aria-selected", "aria-readonly", "aria-required",
    "aria-valuenow", "aria-valuemin", "aria-valuemax", "nonce",
    "accesskey", "datetime", "srcdoc", "popovertarget",
    "popovertargetaction", "autocapitalize", "enterkeyhint",
    "low", "high", "optimum",
};

static gboolean nd_reflected_attr_is_global(const char *name);
static gboolean nd_node_is_custom_element(const nd_node *n);

static JSValue
nd_element_attr_getter(JSContext *ctx, JSValueConst this_val, int magic)
{
    const char *const *names = nd_reflected_attr_names;
    if (magic < 0 || magic >= (int)G_N_ELEMENTS(nd_reflected_attr_names))
        return JS_NewString(ctx, "");
    const nd_node *n = nd_unwrap_element(this_val);
    if (!n) return JS_NewString(ctx, "");
    if (nd_node_is_custom_element(n) && !nd_reflected_attr_is_global(names[magic]))
        return JS_UNDEFINED;
    const char *v = nd_element_get_attr(n, names[magic]);
    gboolean is_url_attr = (magic == 3 || magic == 9 || magic == 39);
    if (is_url_attr) {
        if (!v || !*v) return JS_NewString(ctx, "");
        nd_js *js = js_from_ctx(ctx);
        const char *base = js ? js->current_url : NULL;
        if (base && *base) {
            char *resolved = nd_url_resolve(base, v);
            if (resolved) {
                JSValue ret = JS_NewString(ctx, resolved);
                g_free(resolved);
                return ret;
            }
        }
    }
    return JS_NewString(ctx, v ? v : "");
}

static gboolean
nd_reflected_attr_is_global(const char *name)
{
    static const char *const global_attrs[] = {
        "title", "lang", "dir", "spellcheck", "contenteditable", "slot",
        "is", "role", "nonce", "accesskey", "autocapitalize", "enterkeyhint",
        "inputmode", "translate",
    };
    if (!name) return FALSE;
    if (g_str_has_prefix(name, "aria-")) return TRUE;
    for (gsize i = 0; i < G_N_ELEMENTS(global_attrs); i++)
        if (strcmp(name, global_attrs[i]) == 0) return TRUE;
    return FALSE;
}

static gboolean
nd_node_is_custom_element(const nd_node *n)
{
    return n && n->kind == ND_NODE_ELEMENT && n->name &&
           strchr(n->name, '-') != NULL;
}

static JSValue
nd_element_attr_setter(JSContext *ctx, JSValueConst this_val, JSValueConst val, int magic)
{
    const char *const *names = nd_reflected_attr_names;
    if (magic < 0 || magic >= (int)G_N_ELEMENTS(nd_reflected_attr_names))
        return JS_UNDEFINED;
    nd_node *n = nd_unwrap_element_mut(this_val);
    if (!n) return JS_UNDEFINED;
    if (nd_node_is_custom_element(n) && !nd_reflected_attr_is_global(names[magic])) {
        JS_DefinePropertyValueStr(ctx, this_val, names[magic],
                                  JS_DupValue(ctx, val), JS_PROP_C_W_E);
        return JS_UNDEFINED;
    }
    const char *s = JS_ToCString(ctx, val);
    if (s) {
        nd_js_set_attr_recorded(js_from_ctx(ctx), n, names[magic], s);
        if (magic == 3 && n->name && strcmp(n->name, "img") == 0) {
            n->flags &= ~ND_NODE_IMG_LOAD_FIRED;
            nd_js_start_image_load(js_from_ctx(ctx), n, s);
        }
        if (magic == 3 && n->name && strcmp(n->name, "iframe") == 0)
            nd_js_schedule_iframe_load(js_from_ctx(ctx), n);
        JS_FreeCString(ctx, s);
    }
    return JS_UNDEFINED;
}

static const char *
nd_dir_canonical(const char *v)
{
    if (!v) return "";
    if (g_ascii_strcasecmp(v, "ltr") == 0)  return "ltr";
    if (g_ascii_strcasecmp(v, "rtl") == 0)  return "rtl";
    if (g_ascii_strcasecmp(v, "auto") == 0) return "auto";
    return "";
}

static JSValue
nd_element_get_dir(JSContext *ctx, JSValueConst this_val)
{
    const nd_node *n = nd_unwrap_element(this_val);
    const char *v = n ? nd_element_get_attr(n, "dir") : NULL;
    return JS_NewString(ctx, nd_dir_canonical(v));
}

static JSValue
nd_element_set_dir(JSContext *ctx, JSValueConst this_val, JSValueConst val)
{
    nd_node *n = nd_unwrap_element_mut(this_val);
    if (!n) return JS_UNDEFINED;
    const char *s = JS_ToCString(ctx, val);
    if (s) {
        nd_js_set_attr_recorded(js_from_ctx(ctx), n, "dir", s);
        JS_FreeCString(ctx, s);
    }
    return JS_UNDEFINED;
}

static JSValue
nd_element_get_translate(JSContext *ctx, JSValueConst this_val)
{
    (void)ctx;
    const nd_node *n = nd_unwrap_element(this_val);
    for (; n; n = n->parent) {
        if (n->kind != ND_NODE_ELEMENT) continue;
        const char *v = nd_element_get_attr(n, "translate");
        if (!v) continue;
        if (g_ascii_strcasecmp(v, "no") == 0) return JS_FALSE;
        if (*v == '\0' || g_ascii_strcasecmp(v, "yes") == 0) return JS_TRUE;
    }
    return JS_TRUE;
}

static JSValue
nd_element_set_translate(JSContext *ctx, JSValueConst this_val, JSValueConst val)
{
    nd_node *n = nd_unwrap_element_mut(this_val);
    if (!n) return JS_UNDEFINED;
    nd_js_set_attr_recorded(js_from_ctx(ctx), n, "translate",
                            JS_ToBool(ctx, val) ? "yes" : "no");
    return JS_UNDEFINED;
}

typedef struct nd_int_attr_def {
    const char *attr;
    int         dflt;
    int         lo;
    int         hi;
} nd_int_attr_def;

static const nd_int_attr_def g_int_attrs[] = {
    { "maxlength", -1, G_MININT, G_MAXINT },
    { "minlength", -1, G_MININT, G_MAXINT },
    { "size",       0, G_MININT, G_MAXINT },
    { "cols",      20, G_MININT, G_MAXINT },
    { "rows",       2, G_MININT, G_MAXINT },
    { "span",       1, 1,        1000     },
    { "colspan",    1, 1,        1000     },
    { "rowspan",    1, 0,        65534    },
    { "width",      0, G_MININT, G_MAXINT },
    { "height",     0, G_MININT, G_MAXINT },
    { "start",      1, G_MININT, G_MAXINT },
};

static int32_t
nd_int_attr_clamp(const nd_int_attr_def *d, long v)
{
    if (v < d->lo) return d->lo;
    if (v > d->hi) return d->hi;
    return (int32_t)v;
}

static JSValue
nd_element_int_attr_getter(JSContext *ctx, JSValueConst this_val, int magic)
{
    if (magic < 0 || magic >= (int)G_N_ELEMENTS(g_int_attrs))
        return JS_NewInt32(ctx, 0);
    const nd_node *n = nd_unwrap_element(this_val);
    if (!n) return JS_NewInt32(ctx, g_int_attrs[magic].dflt);
    const char *v = nd_element_get_attr(n, g_int_attrs[magic].attr);
    if (!v) {
        gboolean is_w = strcmp(g_int_attrs[magic].attr, "width") == 0;
        gboolean is_h = strcmp(g_int_attrs[magic].attr, "height") == 0;
        if (is_w || is_h) {
            if (n->name && strcmp(n->name, "img") == 0) {
                const nd_image *im = nd_js_image_for_node(js_from_ctx(ctx), n);
                if (im)
                    return JS_NewInt32(ctx, is_w ? im->natural_width
                                                 : im->natural_height);
            } else if (n->name && strcmp(n->name, "canvas") == 0) {
                return JS_NewInt32(ctx, is_w ? 300 : 150);
            }
        }
        return JS_NewInt32(ctx, g_int_attrs[magic].dflt);
    }
    char *end = NULL;
    long n_val = strtol(v, &end, 10);
    if (!end || end == v) return JS_NewInt32(ctx, g_int_attrs[magic].dflt);
    return JS_NewInt32(ctx, nd_int_attr_clamp(&g_int_attrs[magic], n_val));
}

static JSValue
nd_element_int_attr_setter(JSContext *ctx, JSValueConst this_val,
                           JSValueConst val, int magic)
{
    if (magic < 0 || magic >= (int)G_N_ELEMENTS(g_int_attrs))
        return JS_UNDEFINED;
    nd_node *n = nd_unwrap_element_mut(this_val);
    if (!n) return JS_UNDEFINED;
    int32_t iv = 0;
    if (JS_ToInt32(ctx, &iv, val) < 0) return JS_UNDEFINED;
    iv = nd_int_attr_clamp(&g_int_attrs[magic], iv);
    char buf[32];
    g_snprintf(buf, sizeof buf, "%d", (int)iv);
    nd_js_set_attr_recorded(js_from_ctx(ctx), n, g_int_attrs[magic].attr, buf);
    return JS_UNDEFINED;
}

static JSValue
nd_element_get_tabIndex(JSContext *ctx, JSValueConst this_val)
{
    (void)ctx;
    const nd_node *n = nd_unwrap_element(this_val);
    if (!n) return JS_NewInt32(ctx, -1);
    const char *v = nd_element_get_attr(n, "tabindex");
    if (!v) {
        static const char *const focusable[] = {
            "a", "area", "button", "input", "select", "textarea", NULL,
        };
        return JS_NewInt32(ctx, nd_node_name_is_any_of(n, focusable) ? 0 : -1);
    }
    return JS_NewInt32(ctx, nd_parse_int(v, 0, G_MININT, G_MAXINT));
}

static JSValue
nd_element_set_tabIndex(JSContext *ctx, JSValueConst this_val, JSValueConst val)
{
    nd_node *n = nd_unwrap_element_mut(this_val);
    if (!n) return JS_UNDEFINED;
    int32_t iv = 0;
    if (JS_ToInt32(ctx, &iv, val) == 0) {
        char buf[16];
        g_snprintf(buf, sizeof buf, "%d", iv);
        nd_js_set_attr_recorded(js_from_ctx(ctx), n, "tabindex", buf);
    }
    return JS_UNDEFINED;
}

typedef struct {
    const char        *attr;
    const char *const *kw;
    gsize              nkw;
    const char        *missing;
    const char        *invalid;
} nd_enum_attr_def;

static const char *const kw_loading[]   = { "lazy", "eager" };
static const char *const kw_decoding[]  = { "sync", "async", "auto" };
static const char *const kw_method[]    = { "get", "post", "dialog" };
static const char *const kw_crossorig[] = { "anonymous", "use-credentials" };
static const char *const kw_referrer[]  = {
    "no-referrer", "no-referrer-when-downgrade", "same-origin", "origin",
    "strict-origin", "origin-when-cross-origin",
    "strict-origin-when-cross-origin", "unsafe-url",
};

enum {
    ND_ENUM_LOADING, ND_ENUM_DECODING, ND_ENUM_METHOD,
    ND_ENUM_CROSSORIGIN, ND_ENUM_REFERRERPOLICY,
};

static const nd_enum_attr_def g_enum_attrs[] = {
    [ND_ENUM_LOADING]        = { "loading",        kw_loading,   2, "eager", "eager" },
    [ND_ENUM_DECODING]       = { "decoding",       kw_decoding,  3, "auto",  "auto"  },
    [ND_ENUM_METHOD]         = { "method",         kw_method,    3, "get",   "get"   },
    [ND_ENUM_CROSSORIGIN]    = { "crossorigin",    kw_crossorig, 2, NULL,    "anonymous" },
    [ND_ENUM_REFERRERPOLICY] = { "referrerpolicy", kw_referrer,  8, "",      ""      },
};

static JSValue
nd_reflect_enum(JSContext *ctx, const nd_node *n, const nd_enum_attr_def *d)
{
    const char *v = n ? nd_element_get_attr(n, d->attr) : NULL;
    if (!v) return d->missing ? JS_NewString(ctx, d->missing) : JS_NULL;
    for (gsize i = 0; i < d->nkw; i++)
        if (g_ascii_strcasecmp(v, d->kw[i]) == 0)
            return JS_NewString(ctx, d->kw[i]);
    return d->invalid ? JS_NewString(ctx, d->invalid) : JS_NULL;
}

static JSValue
nd_element_enum_getter(JSContext *ctx, JSValueConst this_val, int magic)
{
    if (magic < 0 || magic >= (int)G_N_ELEMENTS(g_enum_attrs)) return JS_NULL;
    return nd_reflect_enum(ctx, nd_unwrap_element(this_val), &g_enum_attrs[magic]);
}

static JSValue
nd_element_enum_setter(JSContext *ctx, JSValueConst this_val, JSValueConst val, int magic)
{
    if (magic < 0 || magic >= (int)G_N_ELEMENTS(g_enum_attrs)) return JS_UNDEFINED;
    nd_node *n = nd_unwrap_element_mut(this_val);
    if (!n) return JS_UNDEFINED;
    const nd_enum_attr_def *d = &g_enum_attrs[magic];
    if (!d->missing && (JS_IsNull(val) || JS_IsUndefined(val))) {
        nd_js_remove_attr_recorded(js_from_ctx(ctx), n, d->attr);
        return JS_UNDEFINED;
    }
    const char *s = JS_ToCString(ctx, val);
    if (s) {
        nd_js_set_attr_recorded(js_from_ctx(ctx), n, d->attr, s);
        JS_FreeCString(ctx, s);
    }
    return JS_UNDEFINED;
}

static const char *const kw_input_types[] = {
    "text", "search", "tel", "url", "email", "password", "date", "month",
    "week", "time", "datetime-local", "number", "range", "color", "checkbox",
    "radio", "file", "submit", "image", "reset", "button", "hidden",
};
static const char *const kw_button_types[] = { "submit", "reset", "button" };

static JSValue
nd_element_get_type(JSContext *ctx, JSValueConst this_val)
{
    const nd_node *n = nd_unwrap_element(this_val);
    if (!n || !n->name) return JS_NewString(ctx, "");
    if (strcmp(n->name, "input") == 0) {
        nd_enum_attr_def d = { "type", kw_input_types,
                               G_N_ELEMENTS(kw_input_types), "text", "text" };
        return nd_reflect_enum(ctx, n, &d);
    }
    if (strcmp(n->name, "button") == 0) {
        nd_enum_attr_def d = { "type", kw_button_types,
                               G_N_ELEMENTS(kw_button_types), "submit", "submit" };
        return nd_reflect_enum(ctx, n, &d);
    }
    const char *v = nd_element_get_attr(n, "type");
    return JS_NewString(ctx, v ? v : "");
}

static JSValue
nd_element_set_type(JSContext *ctx, JSValueConst this_val, JSValueConst val)
{
    nd_node *n = nd_unwrap_element_mut(this_val);
    if (!n) return JS_UNDEFINED;
    const char *s = JS_ToCString(ctx, val);
    if (s) {
        nd_js_set_attr_recorded(js_from_ctx(ctx), n, "type", s);
        JS_FreeCString(ctx, s);
    }
    return JS_UNDEFINED;
}

static gboolean
nd_node_in_template_content(const nd_node *n)
{
    for (const nd_node *p = n; p; p = p->parent)
        if ((p->flags & ND_NODE_TEMPLATE_CONTENT) ||
            nd_node_is_element_named(p, "template"))
            return TRUE;
    return FALSE;
}

static JSValue
nd_element_get_htmlFor(JSContext *ctx, JSValueConst this_val)
{
    const nd_node *n = nd_unwrap_element(this_val);
    if (!n) return JS_NewString(ctx, "");
    const char *v = nd_element_get_attr(n, "for");
    return JS_NewString(ctx, v ? v : "");
}

static JSValue
nd_element_set_htmlFor(JSContext *ctx, JSValueConst this_val, JSValueConst val)
{
    nd_node *n = nd_unwrap_element_mut(this_val);
    if (!n) return JS_UNDEFINED;
    const char *s = JS_ToCString(ctx, val);
    if (s) {
        nd_js_set_attr_recorded(js_from_ctx(ctx), n, "for", s);
        JS_FreeCString(ctx, s);
    }
    return JS_UNDEFINED;
}

static const char *kBoolAttrs[] = {
    "open", "selected", "multiple", "readonly", "autofocus",
    "controls", "loop", "muted", "autoplay", "defer", "async",
    "novalidate",
    "ismap", "draggable", "reversed", "playsinline",
    "default", "inert", "nomodule", "formnovalidate",
    "required",
};

static JSValue
nd_element_async_method(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
    if (argc < 1 || !JS_IsFunction(ctx, argv[0])) return JS_NewInt32(ctx, 0);
    JSValue bind = JS_GetPropertyStr(ctx, argv[0], "bind");
    JSValue cb = JS_UNDEFINED;
    if (JS_IsFunction(ctx, bind)) {
        JSValueConst args[1] = { this_val };
        cb = JS_Call(ctx, bind, argv[0], 1, args);
    }
    JS_FreeValue(ctx, bind);
    if (JS_IsException(cb)) return cb;
    if (!JS_IsFunction(ctx, cb)) {
        JS_FreeValue(ctx, cb);
        cb = JS_DupValue(ctx, argv[0]);
    }
    JSValue delay = argc > 1 ? JS_DupValue(ctx, argv[1]) : JS_NewInt32(ctx, 0);
    JSValueConst args[2] = { cb, delay };
    JSValue ret = nd_js_setTimeout(ctx, JS_UNDEFINED, 2, args, 0);
    JS_FreeValue(ctx, delay);
    JS_FreeValue(ctx, cb);
    return ret;
}

static JSValue
nd_element_cancelAsync(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
    return nd_js_clearTimer(ctx, this_val, argc, argv);
}

static JSValue
nd_element_boolattr_getter(JSContext *ctx, JSValueConst this_val, int magic)
{
    if (magic < 0 || magic >= (int)G_N_ELEMENTS(kBoolAttrs)) return JS_FALSE;
    const nd_node *n = nd_unwrap_element(this_val);
    if (!n) return JS_FALSE;
    if (strcmp(kBoolAttrs[magic], "async") == 0 && !nd_node_is_element_named(n, "script"))
        return JS_NewCFunction(ctx, nd_element_async_method, "async", 2);
    return nd_element_get_attr(n, kBoolAttrs[magic]) ? JS_TRUE : JS_FALSE;
}

static JSValue
nd_element_boolattr_setter(JSContext *ctx, JSValueConst this_val, JSValueConst val, int magic)
{
    if (magic < 0 || magic >= (int)G_N_ELEMENTS(kBoolAttrs)) return JS_UNDEFINED;
    nd_node *n = nd_unwrap_element_mut(this_val);
    if (!n) return JS_UNDEFINED;
    if (strcmp(kBoolAttrs[magic], "async") == 0 && !nd_node_is_element_named(n, "script")) {
        JS_DefinePropertyValueStr(ctx, this_val, "async", JS_DupValue(ctx, val),
                                  JS_PROP_WRITABLE | JS_PROP_CONFIGURABLE);
        return JS_UNDEFINED;
    }
    nd_js *_j = js_from_ctx(ctx);
    gboolean to_set = JS_ToBool(ctx, val) ? TRUE : FALSE;
    gboolean was_open = nd_element_get_attr(n, kBoolAttrs[magic]) != NULL;
    if (to_set) nd_js_set_attr_recorded(_j, n, kBoolAttrs[magic], "");
    else        nd_js_remove_attr_recorded(_j, n, kBoolAttrs[magic]);
    if (strcmp(kBoolAttrs[magic], "open") == 0 && was_open != to_set &&
        nd_node_is_element_named(n, "details"))
        nd_js_details_toggle_open(_j, n, to_set);
    return JS_UNDEFINED;
}

static JSValue
nd_element_get_textContent(JSContext *ctx, JSValueConst this_val)
{
    const nd_node *n = nd_unwrap_element(this_val);
    if (!n) return JS_NULL;
    char *t = nd_node_collect_all_text(n);
    JSValue v = JS_NewString(ctx, t ? t : "");
    g_free(t);
    return v;
}

static JSValue
nd_element_get_text(JSContext *ctx, JSValueConst this_val)
{
    const nd_node *n = nd_unwrap_element(this_val);
    if (!n || n->kind != ND_NODE_ELEMENT || !n->name) return JS_UNDEFINED;
    if (g_ascii_strcasecmp(n->name, "option") == 0) {
        char *t = nd_option_text_dup(n);
        JSValue v = JS_NewString(ctx, t ? t : "");
        g_free(t);
        return v;
    }
    if (g_ascii_strcasecmp(n->name, "a") == 0)
        return nd_element_get_textContent(ctx, this_val);
    if (g_ascii_strcasecmp(n->name, "script") == 0 ||
        g_ascii_strcasecmp(n->name, "title") == 0) {
        GString *buf = g_string_new(NULL);
        for (const nd_node *c = n->first_child; c; c = c->next_sibling)
            if (c->kind == ND_NODE_TEXT && c->text)
                g_string_append(buf, c->text);
        JSValue v = JS_NewString(ctx, buf->str ? buf->str : "");
        g_string_free(buf, TRUE);
        return v;
    }
    return JS_UNDEFINED;
}

static JSValue
nd_element_set_text(JSContext *ctx, JSValueConst this_val, JSValueConst val)
{
    const nd_node *n = nd_unwrap_element(this_val);
    if (!n || n->kind != ND_NODE_ELEMENT || !n->name) return JS_UNDEFINED;
    if (g_ascii_strcasecmp(n->name, "option") == 0 ||
        g_ascii_strcasecmp(n->name, "a")      == 0 ||
        g_ascii_strcasecmp(n->name, "script") == 0 ||
        g_ascii_strcasecmp(n->name, "title")  == 0)
        return nd_element_set_textContent(ctx, this_val, val);
    return JS_UNDEFINED;
}

static JSValue nd_element_get_select_length(JSContext *ctx, JSValueConst this_val);
static JSValue nd_element_get_form_elements(JSContext *ctx, JSValueConst this_val);
static JSValue nd_array_item(JSContext *ctx, JSValueConst this_val,
                             int argc, JSValueConst *argv);
static JSValue nd_array_namedItem(JSContext *ctx, JSValueConst this_val,
                                  int argc, JSValueConst *argv);
static JSValue nd_form_elements_named_lookup(JSContext *ctx,
                                             JSValueConst this_val,
                                             const char *name);
static JSValue nd_form_elements_namedItem(JSContext *ctx, JSValueConst this_val,
                                          int argc, JSValueConst *argv);

static JSValue
nd_element_get_text_length(JSContext *ctx, JSValueConst this_val)
{
    const nd_node *n = nd_unwrap_element(this_val);
    if (!n) return JS_NewInt32(ctx, 0);
    if (n->kind == ND_NODE_TEXT || n->kind == ND_NODE_COMMENT)
        return JS_NewInt32(ctx, n->text ? (int)g_utf8_strlen(n->text, -1) : 0);
    if (n->name && g_ascii_strcasecmp(n->name, "select") == 0)
        return nd_element_get_select_length(ctx, this_val);
    if (n->name && g_ascii_strcasecmp(n->name, "form") == 0) {
        JSValue arr = nd_element_get_form_elements(ctx, this_val);
        JSValue len_v = JS_GetPropertyStr(ctx, arr, "length");
        JS_FreeValue(ctx, arr);
        return len_v;
    }
    return JS_NewInt32(ctx, 0);
}

static JSValue
nd_element_substring_data(JSContext *ctx, JSValueConst this_val,
                          int argc, JSValueConst *argv)
{
    const nd_node *n = nd_unwrap_element(this_val);
    if (!n || !n->text || argc < 1) return JS_NewString(ctx, "");
    int32_t off = 0, cnt = 0;
    JS_ToInt32(ctx, &off, argv[0]);
    if (argc >= 2) JS_ToInt32(ctx, &cnt, argv[1]);
    else cnt = (int32_t)strlen(n->text);
    glong total = g_utf8_strlen(n->text, -1);
    if (off < 0) off = 0;
    if (off > total) off = (int32_t)total;
    if (cnt < 0) cnt = 0;
    if (cnt > total - off) cnt = (int32_t)(total - off);
    const char *start = g_utf8_offset_to_pointer(n->text, off);
    const char *end   = g_utf8_offset_to_pointer(start, cnt);
    return JS_NewStringLen(ctx, start, (gsize)(end - start));
}

static JSValue
nd_element_append_data(JSContext *ctx, JSValueConst this_val,
                       int argc, JSValueConst *argv)
{
    nd_node *n = nd_unwrap_element_mut(this_val);
    if (!n || argc < 1) return JS_UNDEFINED;
    const char *s = JS_ToCString(ctx, argv[0]);
    if (!s) return JS_UNDEFINED;
    char *merged = g_strconcat(n->text ? n->text : "", s, NULL);
    nd_node_replace_text_owned(n, merged);
    JS_FreeCString(ctx, s);
    { nd_js *_j = js_from_ctx(ctx); if (_j) _j->mutated = TRUE; }
    return JS_UNDEFINED;
}

static JSValue
nd_element_delete_data(JSContext *ctx, JSValueConst this_val,
                       int argc, JSValueConst *argv)
{
    nd_node *n = nd_unwrap_element_mut(this_val);
    if (!n || !n->text || argc < 2) return JS_UNDEFINED;
    int32_t off = 0, cnt = 0;
    JS_ToInt32(ctx, &off, argv[0]);
    JS_ToInt32(ctx, &cnt, argv[1]);
    glong total = g_utf8_strlen(n->text, -1);
    if (off < 0) off = 0;
    if (off > total) off = (int32_t)total;
    if (cnt < 0) cnt = 0;
    if (cnt > total - off) cnt = (int32_t)total - off;
    const char *start = g_utf8_offset_to_pointer(n->text, off);
    const char *end   = g_utf8_offset_to_pointer(start, cnt);
    gsize head = (gsize)(start - n->text);
    gsize tail = strlen(end);
    if (head > G_MAXSIZE - 1 || tail > G_MAXSIZE - 1 - head)
        return JS_ThrowRangeError(ctx, "deleteData: combined string too large");
    char *merged = g_malloc(head + tail + 1);
    memcpy(merged, n->text, head);
    memcpy(merged + head, end, tail);
    merged[head + tail] = '\0';
    nd_node_replace_text_owned(n, merged);
    { nd_js *_j = js_from_ctx(ctx); if (_j) _j->mutated = TRUE; }
    return JS_UNDEFINED;
}

static JSValue
nd_element_insert_data(JSContext *ctx, JSValueConst this_val,
                       int argc, JSValueConst *argv)
{
    nd_node *n = nd_unwrap_element_mut(this_val);
    if (!n || argc < 2) return JS_UNDEFINED;
    int32_t off = 0;
    JS_ToInt32(ctx, &off, argv[0]);
    const char *ins = JS_ToCString(ctx, argv[1]);
    if (!ins) return JS_UNDEFINED;
    glong total = n->text ? g_utf8_strlen(n->text, -1) : 0;
    if (off < 0) off = 0;
    if (off > total) off = (int32_t)total;
    const char *p = n->text ? g_utf8_offset_to_pointer(n->text, off) : "";
    gsize head = n->text ? (gsize)(p - n->text) : 0;
    gsize tail = n->text ? strlen(p) : 0;
    gsize ilen = strlen(ins);
    if (head > G_MAXSIZE - 1 ||
        ilen > G_MAXSIZE - 1 - head ||
        tail > G_MAXSIZE - 1 - head - ilen) {
        JS_FreeCString(ctx, ins);
        return JS_ThrowRangeError(ctx, "insertData: combined string too large");
    }
    char *merged = g_malloc(head + ilen + tail + 1);
    if (head) memcpy(merged, n->text, head);
    memcpy(merged + head, ins, ilen);
    if (tail) memcpy(merged + head + ilen, p, tail);
    merged[head + ilen + tail] = '\0';
    nd_node_replace_text_owned(n, merged);
    JS_FreeCString(ctx, ins);
    { nd_js *_j = js_from_ctx(ctx); if (_j) _j->mutated = TRUE; }
    return JS_UNDEFINED;
}

static JSValue
nd_element_replace_data(JSContext *ctx, JSValueConst this_val,
                        int argc, JSValueConst *argv)
{
    nd_node *n = nd_unwrap_element_mut(this_val);
    if (!n || argc < 3) return JS_UNDEFINED;
    int32_t off = 0, cnt = 0;
    JS_ToInt32(ctx, &off, argv[0]);
    JS_ToInt32(ctx, &cnt, argv[1]);
    const char *ins = JS_ToCString(ctx, argv[2]);
    if (!ins) return JS_UNDEFINED;
    const char *cur = n->text ? n->text : "";
    glong total = g_utf8_strlen(cur, -1);
    if (off < 0) off = 0;
    if (off > total) off = (int32_t)total;
    if (cnt < 0) cnt = 0;
    if (cnt > total - off) cnt = (int32_t)total - off;
    const char *start = g_utf8_offset_to_pointer(cur, off);
    const char *end   = g_utf8_offset_to_pointer(start, cnt);
    gsize head = (gsize)(start - cur);
    gsize tail = strlen(end);
    gsize ilen = strlen(ins);
    if (head > G_MAXSIZE - 1 ||
        ilen > G_MAXSIZE - 1 - head ||
        tail > G_MAXSIZE - 1 - head - ilen) {
        JS_FreeCString(ctx, ins);
        return JS_ThrowRangeError(ctx, "replaceData: combined string too large");
    }
    char *merged = g_malloc(head + ilen + tail + 1);
    memcpy(merged, cur, head);
    memcpy(merged + head, ins, ilen);
    memcpy(merged + head + ilen, end, tail);
    merged[head + ilen + tail] = '\0';
    nd_node_replace_text_owned(n, merged);
    JS_FreeCString(ctx, ins);
    { nd_js *_j = js_from_ctx(ctx); if (_j) _j->mutated = TRUE; }
    return JS_UNDEFINED;
}

static JSValue
nd_element_split_text(JSContext *ctx, JSValueConst this_val,
                      int argc, JSValueConst *argv)
{
    nd_node *n = nd_unwrap_element_mut(this_val);
    if (!n || n->kind != ND_NODE_TEXT || !n->text || argc < 1) return JS_NULL;
    int32_t off = 0;
    JS_ToInt32(ctx, &off, argv[0]);
    glong total = g_utf8_strlen(n->text, -1);
    if (off < 0) off = 0;
    if (off > total) off = (int32_t)total;
    const char *split = g_utf8_offset_to_pointer(n->text, off);
    char *tail_text = g_strdup(split);
    gsize head_len = (gsize)(split - n->text);
    char *head = g_strndup(n->text, head_len);
    nd_node_replace_text_owned(n, head);
    nd_node *tail = nd_node_new_text(tail_text);
    if (n->parent) {
        tail->parent = n->parent;
        tail->prev_sibling = n;
        tail->next_sibling = n->next_sibling;
        if (n->next_sibling) n->next_sibling->prev_sibling = tail;
        else n->parent->last_child = tail;
        n->next_sibling = tail;
    } else if (js_from_ctx(ctx)) {
        g_hash_table_add(js_from_ctx(ctx)->orphan_nodes, tail);
    }
    { nd_js *_j = js_from_ctx(ctx); if (_j) _j->mutated = TRUE; }
    return nd_make_element(ctx, tail);
}

static JSValue
nd_element_get_nodeValue(JSContext *ctx, JSValueConst this_val)
{
    const nd_node *n = nd_unwrap_element(this_val);
    if (!n) return JS_NULL;
    if (n->kind == ND_NODE_TEXT || n->kind == ND_NODE_COMMENT)
        return JS_NewString(ctx, n->text ? n->text : "");
    return JS_NULL;
}

static JSValue
nd_element_get_wholeText(JSContext *ctx, JSValueConst this_val)
{
    const nd_node *n = nd_unwrap_element(this_val);
    if (!n || n->kind != ND_NODE_TEXT) return JS_UNDEFINED;
    const nd_node *start = n;
    while (start->prev_sibling && start->prev_sibling->kind == ND_NODE_TEXT)
        start = start->prev_sibling;
    GString *s = g_string_new(NULL);
    for (const nd_node *c = start; c && c->kind == ND_NODE_TEXT;
         c = c->next_sibling)
        g_string_append(s, c->text ? c->text : "");
    JSValue v = JS_NewStringLen(ctx, s->str, s->len);
    g_string_free(s, TRUE);
    return v;
}

static JSValue
nd_element_set_nodeValue(JSContext *ctx, JSValueConst this_val, JSValueConst val)
{
    nd_node *n = nd_unwrap_element_mut(this_val);
    if (!n) return JS_UNDEFINED;
    if (n->kind != ND_NODE_TEXT && n->kind != ND_NODE_COMMENT) return JS_UNDEFINED;
    const char *s = JS_ToCString(ctx, val);
    if (s) {
        char *old_copy = n->text ? g_strdup(n->text) : g_strdup("");
        nd_node_replace_text_owned(n, g_strdup(s));
        JS_FreeCString(ctx, s);
        nd_js *_j = js_from_ctx(ctx);
        if (_j) {
            _j->mutated = TRUE;
            if (n->kind == ND_NODE_TEXT)
                nd_js_record_character_data(_j, n, old_copy);
        }
        g_free(old_copy);
    }
    return JS_UNDEFINED;
}

static JSValue
nd_element_get_id(JSContext *ctx, JSValueConst this_val)
{
    const nd_node *n = nd_unwrap_element(this_val);
    if (!n) return JS_NULL;
    const char *v = nd_element_get_attr(n, "id");
    return JS_NewString(ctx, v ? v : "");
}

static JSValue
nd_element_set_id(JSContext *ctx, JSValueConst this_val, JSValueConst val)
{
    nd_node *n = nd_unwrap_element_mut(this_val);
    if (!n) return JS_UNDEFINED;
    const char *s = JS_ToCString(ctx, val);
    if (s) {
        nd_js_set_attr_recorded(js_from_ctx(ctx), n, "id", s);
        JS_FreeCString(ctx, s);
    }
    return JS_UNDEFINED;
}

