static JSValue
nd_make_token_list(JSContext *ctx, nd_node *n, const char *attr)
{
    if (!n) return JS_NULL;
    JSValue obj = JS_NewObjectClass(ctx, nd_token_list_class_id);
    if (JS_IsException(obj)) return obj;
    nd_token_list_back *b = g_new0(nd_token_list_back, 1);
    b->n = n;
    b->attr = attr;
    JS_SetOpaque(obj, b);
    return obj;
}

