static gboolean
microdata_has_itemprop(const nd_node *n)
{
    const char *v = nd_element_get_attr(n, "itemprop");
    return v && *v;
}

static gboolean
microdata_has_itemscope(const nd_node *n)
{
    return nd_element_get_attr(n, "itemscope") != NULL;
}

static JSValue
nd_element_get_itemScope(JSContext *ctx, JSValueConst this_val)
{
    const nd_node *n = nd_unwrap_element(this_val);
    return JS_NewBool(ctx, n && microdata_has_itemscope(n));
}

static JSValue
nd_element_set_itemScope(JSContext *ctx, JSValueConst this_val, JSValueConst val)
{
    nd_node *n = nd_unwrap_element_mut(this_val);
    if (!n) return JS_UNDEFINED;
    if (JS_ToBool(ctx, val))
        nd_js_set_attr_recorded(js_from_ctx(ctx), n, "itemscope", "");
    else
        nd_js_remove_attr_recorded(js_from_ctx(ctx), n, "itemscope");
    return JS_UNDEFINED;
}

