static JSValue
nd_window_matchMedia(JSContext *ctx, JSValueConst this_val,
                     int argc, JSValueConst *argv)
{
    (void)this_val;
    const char *q = argc > 0 ? JS_ToCString(ctx, argv[0]) : NULL;
    JSValue mql = JS_NewObject(ctx);
    gboolean matches = nd_css_media_query_matches(q);
    JS_SetPropertyStr(ctx, mql, "matches", matches ? JS_TRUE : JS_FALSE);
    JS_SetPropertyStr(ctx, mql, "media", JS_NewString(ctx, q ? q : ""));
    JS_SetPropertyStr(ctx, mql, "_listeners", JS_NewArray(ctx));
    nd_bind_fn(ctx, mql, "addListener",       nd_mql_addListener, 1);
    nd_bind_fn(ctx, mql, "removeListener",    nd_mql_removeListener, 1);
    nd_bind_fn(ctx, mql, "addEventListener",  nd_target_addEventListener, 2);
    nd_bind_fn(ctx, mql, "removeEventListener", nd_target_removeEventListener, 2);
    if (q) JS_FreeCString(ctx, q);
    return mql;
}

