static JSValue
nd_element_get_scrollTop(JSContext *ctx, JSValueConst this_val)
{
    (void)ctx;
    const nd_box *b = nd_box_for_this(ctx, this_val);
    if (!b) return JS_NewInt32(ctx, 0);
    return JS_NewInt32(ctx, (int)(b->scroll_y + 0.5));
}

static JSValue
nd_element_get_scrollLeft(JSContext *ctx, JSValueConst this_val)
{
    (void)ctx;
    const nd_box *b = nd_box_for_this(ctx, this_val);
    if (!b) return JS_NewInt32(ctx, 0);
    return JS_NewInt32(ctx, (int)(b->scroll_x + 0.5));
}

static JSValue
nd_element_get_scrollHeight(JSContext *ctx, JSValueConst this_val)
{
    const nd_box *b = nd_box_for_this(ctx, this_val);
    if (!b) return JS_NewInt32(ctx, 0);
    double h = b->content_height + b->padding.top + b->padding.bottom
             + (b->scroll_max_y > 0 ? b->scroll_max_y : 0);
    if (h < 0) h = 0;
    return JS_NewInt32(ctx, (int)(h + 0.5));
}

static JSValue
nd_element_get_scrollWidth(JSContext *ctx, JSValueConst this_val)
{
    const nd_box *b = nd_box_for_this(ctx, this_val);
    if (!b) return JS_NewInt32(ctx, 0);
    double w = b->content_width + b->padding.left + b->padding.right
             + (b->scroll_max_x > 0 ? b->scroll_max_x : 0);
    if (w < 0) w = 0;
    return JS_NewInt32(ctx, (int)(w + 0.5));
}

static JSValue
nd_element_set_scrollTop(JSContext *ctx, JSValueConst this_val, JSValueConst val)
{
    double v;
    if (JS_ToFloat64(ctx, &v, val) != 0) return JS_UNDEFINED;
    const nd_box *cb = nd_box_for_this(ctx, this_val);
    if (!cb) return JS_UNDEFINED;
    nd_box *b = (nd_box *)cb;
    double max = b->scroll_max_y > 0 ? b->scroll_max_y : 0;
    if (v < 0) v = 0;
    if (v > max) v = max;
    if (v == b->scroll_y) return JS_UNDEFINED;
    b->scroll_y = v;
    nd_js *js = js_from_ctx(ctx);
    if (js) {
        if (js->repaint_cb) js->repaint_cb(js->repaint_user_data);
        const nd_node *el = nd_unwrap_element(this_val);
        if (el) nd_js_dispatch_event(js, el, "scroll", NULL);
    }
    return JS_UNDEFINED;
}

static JSValue
nd_element_set_scrollLeft(JSContext *ctx, JSValueConst this_val, JSValueConst val)
{
    double v;
    if (JS_ToFloat64(ctx, &v, val) != 0) return JS_UNDEFINED;
    const nd_box *cb = nd_box_for_this(ctx, this_val);
    if (!cb) return JS_UNDEFINED;
    nd_box *b = (nd_box *)cb;
    double max = b->scroll_max_x > 0 ? b->scroll_max_x : 0;
    if (v < 0) v = 0;
    if (v > max) v = max;
    if (v == b->scroll_x) return JS_UNDEFINED;
    b->scroll_x = v;
    nd_js *js = js_from_ctx(ctx);
    if (js) {
        if (js->repaint_cb) js->repaint_cb(js->repaint_user_data);
        const nd_node *el = nd_unwrap_element(this_val);
        if (el) nd_js_dispatch_event(js, el, "scroll", NULL);
    }
    return JS_UNDEFINED;
}

